import type { Choice, Mission } from "../../types";

/**
 * M11 — The Co-Creation Studio.
 * All people, organisations and the publishing policy are fictional. Drafts are authored, not generated.
 */

const POLICY =
  "The Commons' publishing policy: (1) Say when AI was used, if an image was generated by AI or if AI-written text is published largely unchanged. (2) Use photos of people only if each of them has signed a consent form, and use only images the Commons owns or has permission to use. (3) A quotation from a published work that is longer than one sentence needs permission. (4) A named member of staff approves everything published, and answers for it.";

const firstMove =
  "Before you start, Fatima's colleague at the library asks: “If the AI tool writes half the poster, who do we go to if something on it is wrong?” What do you tell them?";
const firstChoices: Choice[] = [
  { id: "a", label: "The company behind the AI tool, for the parts it wrote.", verdict: "weaker", explanation: "The company didn't choose to publish the poster. Whoever publishes it answers for it, whichever tool helped." },
  { id: "b", label: "Me, and whoever approves it, whatever the AI wrote.", verdict: "correct", explanation: "AI can suggest, but people choose what is published. That is why recording who contributed what matters: it shows what you checked and decided." },
  { id: "c", label: "It's shared: me for my parts, and the AI for its parts.", verdict: "weaker", explanation: "A tool can't answer to anyone for what it contributed. The responsibility for the final choices is yours." },
];

